import json, sys, os, statistics
from collections import defaultdict
sys.path.insert(0,'/workspace/task_file/scripts')
from cost_model import CostModel, CostConsts, align, HEADS, HIDDEN

def load(name):
    return [json.loads(l) for l in open('/workspace/task_file/input_data/'+name)]

def eval_plan(reqs, groups, shapes):
    # groups: list of (batch_id, [reqs]); shapes: batch_id->seqrep
    reqmap={r['request_id']:r for r in reqs}
    plan=[]
    for bid, rs, srep in groups:
        for r in rs:
            plan.append({'request_id':r['request_id'],'batch_id':bid,
                         'shape':{'seq_align':srep,'heads_align':HEADS,'hidden_align':HIDDEN}})
    cm=CostModel(64)
    return cm.plan_metrics(reqmap, plan)

def exact_groups(reqs, s_rep_fn):
    d=defaultdict(list)
    for r in reqs:
        d[(align(r['prompt_len'],64), r['gen_len'])].append(r)
    groups=[]
    for i,(k,rs) in enumerate(sorted(d.items())):
        groups.append((f"b-{i:04d}", rs, s_rep_fn(k[0])))
    return groups

def rep_fn_factory(reqs, k=8):
    uniq=sorted({align(r['prompt_len'],64) for r in reqs})
    K=min(k,len(uniq))
    if K==len(uniq):
        reps=uniq
    else:
        step=len(uniq)/K
        reps=sorted({uniq[min(len(uniq)-1,int((i+0.5)*step))] for i in range(K-1)} | {uniq[-1]})
    def f(s):
        for rep in reps:
            if rep>=s: return rep
        return reps[-1]
    return f,reps

for name in ['requests_bucket_1.jsonl','requests_bucket_2.jsonl']:
    reqs=load(name)
    f,reps=rep_fn_factory(reqs,8)
    groups=exact_groups(reqs,f)
    m=eval_plan(reqs,groups,[g[2] for g in groups])
    print("="*70)
    print(name,"exact (S,G) grouping, batches=",len(groups),"reps=",reps)
    for k in ['cost','pad_ratio','p95_latency_ms','sequential_timecost']:
        print("  %-20s %.6g"%(k,m[k]))
    print("  pad_tokens",m['pad_tokens'],"real",m['real_tokens'])
EOF
